compile.workshop:
variables {
    global:
        0: a
        1: i
}

rule ("continue for") {
    event {
        Ongoing - Global;
    }
    actions {
        For Global Variable(i, 0, 3, 1);
            Skip If(Compare(Global.i, ==, 1), 1);
            Modify Global Variable(i, Add, 1);
            //__label_continue_2__:
        End;
    }
}

rule ("continue while") {
    event {
        Ongoing - Global;
    }
    actions {
        While(Compare(Global.i, <, 3));
            Skip If(Compare(Global.i, ==, 1), 1);
            Modify Global Variable(i, Add, 1);
            //__label_continue_3__:
        End;
    }
}

rule ("continue do") {
    event {
        Ongoing - Global;
    }
    actions {
        Loop If(Compare(Global.i, ==, 1));
        Modify Global Variable(i, Add, 1);
        Loop If(Compare(Global.i, <, 3));
    }
}

rule ("dynamic goto") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(a, 1);
        Skip(Global.a);
        Set Global Variable(a, 2);
    }
}

rule ("rule start") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(a, 1);
        Loop;
    }
}

